differences AS (SELECT (select coalesce(jsonb_agg(jsonb_build_object('section',s,'object',k,'expected',expected.value->s->k,'actual',actual.value->s->k) order by s,k),'[]')
from unnest(array['functions','catalog','rows']) s
cross join lateral (select jsonb_object_keys(expected.value->s) k union select jsonb_object_keys(actual.value->s) k) keys
where actual.value->s->k is distinct from expected.value->s->k) value FROM actual,expected),
function_differences AS (SELECT v FROM differences,jsonb_array_elements(value) v WHERE v->>'section'='functions'),
catalog_differences AS (SELECT v FROM differences,jsonb_array_elements(value) v WHERE v->>'section'='catalog'),
checks AS (SELECT * FROM (VALUES
 ('expected_manifest_exact',(SELECT encode(sha256(convert_to(value::text,'UTF8')),'hex')='3890d59a668786e863c224ef7bd57f703a675af5f2fcde7e00227d4516ea2bbf' FROM expected)),
 ('dependency_functions_exact',NOT EXISTS(SELECT 1 FROM function_differences)),
 ('dependency_catalog_exact',NOT EXISTS(SELECT 1 FROM catalog_differences)),
 ('target_state_exact',NOT EXISTS(SELECT 1 FROM function_differences WHERE split_part(v->>'object','(',1) IN ('document_direct_source','document_direct_snapshot','document_direct_blockers','document_direct_decision','get_finance_received_document_decision','create_finance_received_document_draft','document_direct_action','validate_direct_document','guard_direct_document_dependencies'))
   AND (SELECT count(*)=9 FROM actual,jsonb_object_keys(value->'functions') k WHERE split_part(k,'(',1) IN ('document_direct_source','document_direct_snapshot','document_direct_blockers','document_direct_decision','get_finance_received_document_decision','create_finance_received_document_draft','document_direct_action','validate_direct_document','guard_direct_document_dependencies'))
