 ('required_security',NOT EXISTS(SELECT 1 FROM function_differences) AND NOT EXISTS(SELECT 1 FROM catalog_differences)),
 ('preserved_functions',NOT EXISTS(SELECT 1 FROM function_differences WHERE v->>'object' IN ('assert_finance_document_route(uuid,text)','build_finance_document_tax_source(uuid)','build_finance_receipt_source(uuid)','build_finance_tax_invoice_source(uuid)','calculate_finance_billable_charge_amounts(numeric,numeric,text,numeric)','cancel_finance_combined_document_draft(uuid,text)','cancel_finance_receipt_draft(uuid,text)','cancel_finance_tax_invoice_draft(uuid,text)','create_finance_combined_document_draft(uuid,boolean,boolean)','create_finance_receipt_draft_from_payment(uuid,boolean)','create_finance_tax_correction_draft(uuid,uuid,uuid,text,text,text,text,date,date,jsonb)','create_finance_tax_invoice_draft(uuid)','current_user_can_issue_combined_documents()','current_user_can_issue_finance_receipts()','current_user_can_issue_finance_tax_invoices()','current_user_can_manage_combined_documents()','current_user_can_manage_finance_receipts()','current_user_can_manage_finance_tax_invoices()','current_user_can_view_finance_receipts()','current_user_can_view_finance_tax_invoices()','current_user_can_void_finance_receipts()','direct_money_lines(jsonb)','direct_money_snapshot(finance_direct_money_receipts)','direct_money_snapshot_before_treasury(finance_direct_money_receipts)','document_logo_evidence(text)','document_tax_snapshot_pre042(jsonb,jsonb,date)','document_tax_source_pre042(uuid)','finance_customer_tax_identity(uuid)','finance_document_invoice_lines(uuid)','finance_invoice_wht_basis_v1(jsonb)','finance_invoice_wht_lines_v2(jsonb)','finance_payment_document_decision(uuid)','finance_structured_wht_amount(numeric,numeric)','finance_tax_invoice_draft_snapshot(jsonb,jsonb,date)','finance_tax_invoice_issue_blockers(jsonb)','finance_vat_treatment(jsonb,boolean,numeric)','generate_finance_document_no(text,date)','get_finance_customer_tax_profile(uuid)','get_finance_document_decision(uuid)','guard_finance_receipt_lifecycle()','guard_receipt_logo_issue()','issue_finance_combined_document(uuid,jsonb,boolean,boolean,boolean,boolean)','issue_finance_receipt(uuid,boolean,jsonb)','issue_finance_tax_invoice(uuid,jsonb,boolean,boolean)','money_allocation_decisions(jsonb,jsonb,boolean)','money_allocation_lock(uuid)','money_allocation_source(uuid)','prepare_finance_document_tax_draft(uuid)','receipt_cancel_pre040(uuid,text)','receipt_create_pre040(uuid,boolean)','receipt_refresh_pre040(uuid)','record_finance_receipt_audit(uuid,text,jsonb)','record_finance_tax_invoice_audit(uuid,text,jsonb)','refresh_finance_combined_document_draft(uuid,timestamp with time zone)','refresh_finance_receipt_draft(uuid)','refresh_finance_tax_invoice_draft(uuid,timestamp with time zone)','save_finance_combined_document_draft(uuid,date,jsonb,timestamp with time zone)','save_finance_tax_invoice_draft(uuid,date,jsonb,timestamp with time zone)','tax_blockers_pre040(jsonb)','tax_cancel_pre040(uuid,text)','tax_correction_authorized(boolean,text)','tax_correction_source(uuid,uuid)','tax_expense_input_vat_status(uuid)','tax_filing_monthly_facts_before_expense(date)','tax_position_source(text,uuid)','tax_position_source_before_expense(text,uuid)','tax_position_source_before_external_input(text,uuid)','tax_refresh_pre040(uuid,timestamp with time zone)','tax_save_pre040(uuid,date,jsonb,timestamp with time zone)','tax_snapshot_pre040(jsonb,jsonb,date)','validate_finance_combined_document()','validate_finance_document_tax_integrity(uuid)','validate_finance_receipt_integrity()','validate_finance_tax_invoice_integrity()','validate_tax_correction_document()','void_finance_receipt(uuid,text,boolean)','vp_direct_frozen_source(jsonb)','vp_distribution_frozen_source(jsonb,jsonb)','vp_distribution_source(uuid)','vp_received_line_economics(numeric,numeric,text)','vp_received_lock(uuid,uuid)','vp_received_source(uuid,uuid)'))),
 ('preserved_catalog_security',NOT EXISTS(SELECT 1 FROM catalog_differences)),
 ('historical_rows_unchanged',(SELECT actual.value->'rows'=expected.value->'rows' FROM actual,expected)),
 ('historical_new_source_columns_null',NOT (exists(select 1 from public.finance_combined_documents r where coalesce(to_jsonb(r)->'direct_money_receipt_id','null'::jsonb)<>'null'::jsonb) or exists(select 1 from public.finance_receipt_invoice_allocations r where coalesce(to_jsonb(r)->'direct_money_receipt_id','null'::jsonb)<>'null'::jsonb or coalesce(to_jsonb(r)->'direct_source_line_id','null'::jsonb)<>'null'::jsonb) or exists(select 1 from public.finance_receipts r where coalesce(to_jsonb(r)->'direct_money_receipt_id','null'::jsonb)<>'null'::jsonb) or exists(select 1 from public.finance_tax_document_corrections r where coalesce(to_jsonb(r)->'direct_money_receipt_id','null'::jsonb)<>'null'::jsonb) or exists(select 1 from public.finance_tax_invoice_items r where coalesce(to_jsonb(r)->'direct_money_receipt_id','null'::jsonb)<>'null'::jsonb or coalesce(to_jsonb(r)->'direct_source_line_id','null'::jsonb)<>'null'::jsonb) or exists(select 1 from public.finance_tax_invoice_source_coverages r where coalesce(to_jsonb(r)->'direct_money_receipt_id','null'::jsonb)<>'null'::jsonb or coalesce(to_jsonb(r)->'direct_source_line_id','null'::jsonb)<>'null'::jsonb) or exists(select 1 from public.finance_tax_invoices r where coalesce(to_jsonb(r)->'direct_money_receipt_id','null'::jsonb)<>'null'::jsonb)))
 ) x(name,pass))
SELECT bool_and(coalesce(pass,false)) AS gate_pass,
 coalesce(jsonb_agg(name ORDER BY name) FILTER(WHERE pass IS DISTINCT FROM true),'[]') AS failed_checks,
 (SELECT coalesce(bool_and(coalesce(pass,false)),false) FROM checks WHERE name IN ('historical_rows_unchanged','historical_new_source_columns_null')) AS historical_rows_unchanged,
 '010093343be8675823b8e9459c979d1dc6efe75959c7f12c0268eecb17db3f9e'::text AS candidate_sha256,
 '3f33c39290834b7bcdcd436b0af957422b400e06e626b3d07d3952569e1e588e'::text AS approved_baseline_sha256,
 (SELECT coalesce(pass,false) FROM checks WHERE name='target_state_exact') AS applied_state_exact,
 (SELECT coalesce(jsonb_agg(v),'[]') FROM function_differences) AS function_differences,
 (SELECT coalesce(jsonb_agg(v),'[]') FROM catalog_differences) AS catalog_differences,
 (SELECT value FROM differences) AS object_differences
FROM checks;
